from math import gcd
from typing import Iterable, Optional, List, Set
from collections import deque


def additive_order(a: int, n: int) -> int:
    a %= n
    return 1 if a == 0 else n // gcd(n, a)


def incoherence_index(atoms: Iterable[int], n: int) -> int:
    F: Set[int] = {a % n for a in atoms}
    if not F:
        return 0
    frontier, visited = {0}, set()
    for level in range(1, n + 1):
        nxt = {(r + a) % n for r in frontier for a in F}
        if 0 in nxt:
            return level
        nxt -= visited
        if not nxt:
            return 0
        visited |= nxt
        frontier = nxt
    return 0


def main() -> None:
    for n in (4, 5, 6, 12):
        for a in range(1, n):
            idx = incoherence_index([a], n)
            assert idx == additive_order(a, n) == n // gcd(n, a)
            print(f'n={n} a={a}: index={idx} = n/gcd(n,a)={n//gcd(n,a)}')


if __name__ == '__main__':
    main()

