from math import gcd


def singleton_incoherence_index(n: int, a: int) -> int:
    """Incoherence index of {a} in Z/nZ = additive order of a = n/gcd(n,a)."""
    a %= n
    if a == 0:
        return 1
    return n // gcd(n, a)

algorithms.pseudocode:
function IncoherenceIndex(F, n):
    F <- { a mod n : a in F }
    if F is empty: return 0
    frontier <- {0}; visited <- {}
    for level in 1 .. n:
        nxt <- { (r + a) mod n : r in frontier, a in F }
        if 0 in nxt: return level
        nxt <- nxt \ visited
        if nxt is empty: return 0     # coherent
        visited <- visited U nxt
        frontier <- nxt
    return 0

